'''Created on 19 feb 2018@author: Enzo CoccaThese classes define the initial state of the instances for Anchor.The __repr__ method is a special method used to represent instances of these classes for debugging purposes.It should return a string that is a well-formatted representation of the object,using the object's attributes to create this string.'''from builtins import objectclass ANC_c(object):    def __init__(self, id_anc, site, anchor_id, obj_partial, author, star_date, end_date, state_conservation, observation, measure, damage, concretion, bio, procedure, desalination_date):        self.id_anc = id_anc        self.site=site        self.anchor_id = anchor_id        self.obj_partial = obj_partial        self.author = author        self.star_date = star_date        self.end_date = end_date        self.state_conservation = state_conservation        self.observation = observation        self.measure = measure        self.damage = damage        self.concretion = concretion        self.bio = bio        self.procedure = procedure        self.desalination_date = desalination_date    def __repr__(self):        return "<ANC_c('%d', '%s','%s', '%s', '%s', '%s', '%s', '%s', '%s', '%s', '%s', '%s', '%s', '%s', '%s')>" % (            self.id_anc, self.site, self.anchor_id, self.obj_partial, self.author, self.star_date, self.end_date, self.state_conservation, self.observation, self.measure, self.damage, self.concretion, self.bio, self.procedure, self.desalination_date)